/**
 * Era-appropriate headlines generated by deterministic templates from actual
 * recorded events (no free-form narrative): ancient chronicles, broadsheets,
 * modern news and futuristic feeds.
 */
import type { Sim } from '../sim/context';
import type { HistoryEvent } from '../sim/types';

function eraStyle(sim: Sim, ev: HistoryEvent): number {
  let era = 1;
  for (const cid of ev.civs) {
    const c = sim.w.civs.get(cid);
    if (c && c.era > era) era = c.era;
  }
  if (!ev.civs.length) {
    for (const c of sim.w.civs.values()) if (c.alive && c.era > era) era = c.era;
  }
  return era;
}

export function headlineFor(sim: Sim, ev: HistoryEvent): string | undefined {
  if (ev.importance < 3) return undefined;
  const era = eraStyle(sim, ev);
  const t = ev.title.replace(/\.$/, '');
  if (era <= 4) return `It is recorded in the year ${ev.year}: ${t}.`;
  if (era <= 6) return `Tidings of the Year ${ev.year} — ${t}!`;
  if (era <= 8) return `EXTRA! ${t.toUpperCase()}`;
  if (era <= 11) return `BREAKING: ${t}`;
  return `[${ev.year}] ${t} // feed`;
}

/** Latest headlines for the newspaper ticker. */
export function recentHeadlines(sim: Sim, count = 8): HistoryEvent[] {
  const out: HistoryEvent[] = [];
  const evs = sim.w.events;
  for (let k = evs.length - 1; k >= 0 && out.length < count; k--) if (evs[k].headline) out.push(evs[k]);
  return out;
}
